// 原私人粮食始终在Common原容器内；本叶只有纯报价和typed recipe，没有第二份可花库存。
#include "birth_care_resources.hpp"
#include <algorithm>
#include <charconv>
#include <tuple>
namespace hanmo::resident {namespace {
// 本域contract以真实接受事实为根，不能借任务/公事合同或任意存在头预留资源。
Status source(const CommonStore& c,const StableId& id){const StableId prefix="family_birth:";if(id.rfind(prefix,0)!=0)return common_failure("BirthCareContractSourceRequired",id);const auto raw=id.substr(prefix.size());Integer number=0;const auto decoded=std::from_chars(raw.data(),raw.data()+raw.size(),number);const auto* head=c.state().facts.find(id);if(decoded.ec!=std::errc{}||decoded.ptr!=raw.data()+raw.size()||number<=0||number>=c.state().next_instance_id||raw!=std::to_string(number)||!head||head->id!=id||head->kind!="family_birth_accepted"||head->domain!="family_birth")return common_failure("BirthCareContractSourceRequired",id);return common_success();}
// 旧预约保存当前原产权；物资不能因承诺就变共同家庭、公库或儿童可任意动用财产。
Status inventory(const CommonStore& c,const BirthCareTerms& terms){const auto* actor=c.actor(terms.payer_actor_id);const auto* bag=c.inventory(terms.source_inventory_id);const Owner owner{Owner::Kind::actor,terms.payer_actor_id,{}};if(!actor||actor->inventory_id!=terms.source_inventory_id||!bag||!owner_equal(bag->owner,owner)||bag->owner.extra||!c.item_definition(terms.food_item_id))return common_failure("BirthCarePrivateInventoryRequired");return common_success();}
// 每项先限范围再相乘，最大360万；有限准备量不能偷偷表示直到成年全部照护。
Outcome<Integer> total(const BirthCareTerms& terms){if(terms.food_per_period<1||terms.food_per_period>10000||terms.prepaid_care_periods<1||terms.prepaid_care_periods>360)return {false,0,common_failure("InvalidBirthCareSupplyAmount").error};return {true,terms.food_per_period*terms.prepaid_care_periods,{}};}
// 真正当面地点是自己的原库存可触及条件；海上锚点不被当作室内粮食交割。
Status at_place(const CommonStore& c,const BirthCareTerms& terms){const auto* actor=c.actor(terms.payer_actor_id);if(!actor||!actor->alive||!actor->available||!actor->action_id.empty())return common_failure("BirthCarePayerUnavailable");auto location=c.resolved_location(actor->id);if(!location.ok)return {false,{},location.error};const auto* at=std::get_if<SettlementLocation>(&location.value);return at&&at->place_id==terms.place_id?common_success():common_failure("BirthCareSupplyNotAtPlace");}
}
Outcome<BirthCareSupplyQuote> preview_birth_care_supply(const CommonStore& c,const BirthCareTerms& terms){auto valid=inventory(c,terms);if(!valid.ok)return {false,{},valid.error};valid=at_place(c,terms);if(!valid.ok)return {false,{},valid.error};auto quantity=total(terms);if(!quantity.ok)return {false,{},quantity.error};const Owner owner{Owner::Kind::actor,terms.payer_actor_id,{}};const auto* bag=c.inventory(terms.source_inventory_id);for(const auto& lot:bag->lots)if(lot.item_id==terms.food_item_id&&owner_equal(lot.owner,owner)&&lot.reserved_by.empty()&&(lot.extra||lot.owner.extra))return {false,{},common_failure("UnsupportedBirthCareLot",lot.id).error};auto available=c.count(bag->id,terms.food_item_id,{owner});if(!available.ok)return {false,{},available.error};if(available.value<quantity.value)return {false,{},common_failure("InsufficientBirthCareSupply").error};return {true,{c.state().identity,terms,quantity.value,bag->revision,available.value},{}};}
Status validate_birth_care_reservation(const CommonStore& c,const BirthCareTerms& terms,const StableId& accepted,Integer remaining){auto valid=source(c,accepted);if(!valid.ok)return valid;valid=inventory(c,terms);if(!valid.ok)return valid;auto maximum=total(terms);if(!maximum.ok)return {false,{},maximum.error};if(remaining<0||remaining>maximum.value)return common_failure("InvalidBirthCareRemainingSupply");const ReservationRef reservation{ReservationRef::Kind::contract,accepted};if(!c.reservation_exists(reservation))return common_failure("BirthCareReservationOwnerRequired",accepted);for(const auto& row:c.state().wallets.rows())for(const auto& held:row.second.reserved)if(held.action_id==reservation)return common_failure("UnexpectedBirthCareMoneyReservation",row.first);Integer actual=0;const Owner owner{Owner::Kind::actor,terms.payer_actor_id,{}};for(const auto& row:c.state().inventories.rows())for(const auto& lot:row.second.lots)if(lot.reserved_by==reservation){if(row.first!=terms.source_inventory_id||lot.item_id!=terms.food_item_id||lot.quantity<=0||!owner_equal(lot.owner,owner)||lot.owner.extra||lot.extra||actual>maximum.value-lot.quantity)return common_failure("UnexpectedBirthCareReservation",lot.id);actual+=lot.quantity;}return actual==remaining?common_success():common_failure("BirthCareReservationAmountMismatch",accepted);}
Outcome<ResourceRecipe> reserve_birth_care_recipe(const CommonStore& c,const BirthCareSupplyQuote& quote,const StableId& accepted){const auto& current=c.state().identity;if(std::tie(current.world_id,current.execution_epoch,current.revision,current.tick)!=std::tie(quote.identity.world_id,quote.identity.execution_epoch,quote.identity.revision,quote.identity.tick))return {false,{},common_failure("StaleBirthCareSupplyQuote").error};auto valid=source(c,accepted);if(!valid.ok)return {false,{},valid.error};auto fresh=preview_birth_care_supply(c,quote.terms);if(!fresh.ok)return {false,{},fresh.error};if(fresh.value.quantity!=quote.quantity||fresh.value.inventory_revision!=quote.inventory_revision||fresh.value.available_before!=quote.available_before)return {false,{},common_failure("BirthCareSupplyChanged").error};valid=validate_birth_care_reservation(c,quote.terms,accepted,0);if(!valid.ok)return {false,{},valid.error};ResourceRecipe recipe;recipe.operations.push_back(ReserveLots{quote.terms.source_inventory_id,quote.terms.food_item_id,quote.quantity,{{Owner::Kind::actor,quote.terms.payer_actor_id,{}}},{ReservationRef::Kind::contract,accepted}});return {true,std::move(recipe),{}};}
Outcome<ResourceRecipe> consume_birth_care_recipe(const CommonStore& c,const BirthCareTerms& terms,const StableId& accepted,Integer remaining,Integer consumed){auto valid=validate_birth_care_reservation(c,terms,accepted,remaining);if(!valid.ok)return {false,{},valid.error};if(consumed!=terms.food_per_period||consumed>remaining)return {false,{},common_failure("InvalidBirthCareConsumption").error};ResourceRecipe recipe;recipe.operations.push_back(ConsumeLots{terms.source_inventory_id,terms.food_item_id,consumed,{{Owner::Kind::actor,terms.payer_actor_id,{}}},{ReservationRef::Kind::contract,accepted}});return {true,std::move(recipe),{}};}
Outcome<ResourceRecipe> release_birth_care_recipe(const CommonStore& c,const BirthCareTerms& terms,const StableId& accepted,Integer remaining){auto valid=validate_birth_care_reservation(c,terms,accepted,remaining);if(!valid.ok)return {false,{},valid.error};ResourceRecipe recipe;recipe.operations.push_back(ReleaseReservationResources{{ReservationRef::Kind::contract,accepted}});return {true,std::move(recipe),{}};}
}
